# اللغة العربية — السنة السابعة، الشعب الأدبية (A/O) — المعهد التربوي الوطني. المحتوى من الكتاب فقط.
BOOK = "AR_7AO"

def F(page, y0, y1, x0=0.05, x1=0.95, cap=""):
    return {"page": page, "rect": [x0, y0, x1, y1], "caption": cap}

def S(h, lines=None, table=None, fig=None):
    d = {"h": h, "lines": lines or []}
    if table: d["table"] = table
    if fig: d["fig"] = fig
    return d

def L(title, pages, objectives, intro, summary, points, app, board, apps=()):
    return {"title": title, "match": [title], "pages": pages, "objectives": objectives, "intro": intro,
            "summary": summary, "points": points, "application": {"q": app[0], "a": app[1]},
            "applications": [{"q": q, "a": a} for q, a in apps], "board": board}

def TXT(title, pages, figs, author, objectives, intro, summary, points, app, analysis, apps=()):
    board = [S("النص" + (f" ({i+1})" if len(figs) > 1 else ""), fig=f) for i, f in enumerate(figs)]
    board += [S("صاحب النص", [author]), S("الفهم والتحليل", analysis)]
    return L(title, pages, objectives, intro, summary, points, app, board, apps)
