   S("عمل اسم الفاعل وصيغ المبالغة", table=[["الحالة", "الحكم"], ["معرف بأل", "يعمل دون شروط"], ["نكرة", "يسبق بمبتدأ أو نفي أو استفهام، ويدل على الحال أو الاستقبال"], ["صيغ المبالغة", "تعمل عمل اسم الفاعل بشروطه"]]),
