L("النقد ومذاهبه", [187, 188],
  ["أن يعرف الطالب النقد لغة واصطلاحا.", "أن يميز النقد الذاتي من الموضوعي، والنظري من التطبيقي.", "أن يتعرف أصول النقد العربي الحديث في التراث."],
  "أسأل: هل الناقد من يعيب الأعمال الأدبية؟",
  "النقد فن تحليل الآثار الأدبية والتعرف إلى عناصرها للانتهاء إلى حكم يتعلق بمبلغها من الإجادة (جبور عبد النور). لغة خلاف النسيئة (دفع الثمن ساعة الشراء)، واصطلاحا دراسة الآثار الأدبية شعرا ونثرا لإدراجها في إطارها وتحديد سماتها الفنية والفكرية، وهو عملية وصفية تقرب النص للقارئ. النقد خلاف التجريح لأنه موضوعي يستند إلى المنهج والمصطلح، مع حضور الذوق: «غربلة الآثار لا غربلة الناس» (نعيمة). وهو ذاتي وموضوعي، ونظري (القضايا والقوانين الفنية) وتطبيقي (تطبيق الأدوات الإجرائية على الأثر). وللنقد العربي جذور منذ الجاهلية في أحكام انطباعية (تحكيم النابغة بين الخنساء وحسان)، وازدهر في العصر الأموي بالمفاضلة والموازنة.",
  ["النقد: تحليل الآثار الأدبية وإصدار حكم عليها.", "لغة: خلاف النسيئة.", "النقد خلاف التجريح: موضوعية المنهج والمصطلح مع الذوق.", "ذاتي/موضوعي ؛ نظري/تطبيقي.", "جذوره: أحكام انطباعية جاهلية (النابغة)، وازدهار أموي."],
  ("ما الفرق بين النقد النظري والنقد التطبيقي؟", "النظري يناقش القضايا والقوانين الفنية التي تحكم الأدب، والتطبيقي يطبق الأدوات الإجرائية (المنهج والمصطلحات) على الأثر المدروس."),
  [S("التعريف", ["فن تحليل الآثار الأدبية والتعرف إلى عناصرها لإصدار حكم يتعلق بمبلغها من الإجادة (جبور عبد النور، المعجم الأدبي).", "لغة: خلاف النسيئة ؛ اصطلاحا: دراسة الآثار الأدبية لإدراجها في إطارها وتحديد سماتها."]),
   S("أنواع النقد", table=[["التقسيم", "النوعان"], ["حسب المعايير", "ذاتي (انطباعي) / موضوعي (منهج ومصطلح)"], ["حسب الوظيفة", "نظري (قضايا وقوانين) / تطبيقي (أدوات إجرائية على الأثر)"]]),
   S("أصول النقد العربي", ["الجاهلية: أحكام انطباعية مرتجلة (تحكيم النابغة الذبياني بين الخنساء وحسان).", "العصر الأموي: ازدهار حقيقي، مع طابع انطباعي قائم على المفاضلة والموازنة."])],
  apps=[("ما معنى قول نعيمة: غربلة الآثار لا غربلة الناس؟", "أن الناقد يحكم على الأعمال الأدبية لا على أصحابها، فالنقد ليس تجريحا."), ("اذكر مثالا للنقد الانطباعي في الجاهلية.", "تحكيم النابغة الذبياني بين الخنساء وحسان بن ثابت.")]),
